import nodemailer from 'nodemailer';
import { buildSmtpTransportOptions } from '@/lib/smtp-transport';

// ─── Logo embarqué en base64 (toujours visible dans tous les clients mail) ────
const LOGO_B64 = 'data:image/png;base64,';

// ─── Transporteur SMTP ────────────────────────────────────────────────────────

// Les options (mode TLS selon le port, validation du certificat, autorité
// privée éventuelle) sont construites par @/lib/smtp-transport : le certificat
// du serveur est TOUJOURS validé, car les liens de réinitialisation de mot de
// passe passent par ce transport. Une configuration invalide lève une erreur,
// récupérée par le try/catch de chaque fonction d'envoi ci-dessous.
function createTransporter() {
  return nodemailer.createTransport(
    buildSmtpTransportOptions({
      SMTP_HOST:           process.env.SMTP_HOST,
      SMTP_PORT:           process.env.SMTP_PORT,
      SMTP_SECURE:         process.env.SMTP_SECURE,
      SMTP_USER:           process.env.SMTP_USER,
      SMTP_PASS:           process.env.SMTP_PASS,
      SMTP_CA_FILE:        process.env.SMTP_CA_FILE,
      SMTP_TLS_SERVERNAME: process.env.SMTP_TLS_SERVERNAME,
    }),
  );
}

