// ─── Texte brut ───────────────────────────────────────────────────────────────

function buildText(prenom: string, username: string, password: string, introText?: string): string {
  const plainIntro = introText
    ? introText.replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]*>/g, '')
      .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
      .replace(/&amp;/g, '&')
    : 'Ton compte animateur a été créé / mis à jour.';
  return `Bonjour ${prenom},

${plainIntro}

Identifiant : ${username}
Mot de passe : ${password}

Connecte-toi via : https://jeunessenogent.cloud/

Xavier GERINETTE — Pôle Jeunesse — Mairie de Nogent-sur-Marne`;
}

// ─── Email : création de compte ───────────────────────────────────────────────

export async function envoyerIdentifiants(data: {
  prenom: string; nom: string; email: string;
  username: string; password: string; espaceAssigne: string;
  subject?: string; introText?: string;
}): Promise<{ success: boolean; error?: string }> {
  try {
    const transporter = createTransporter();
    await transporter.sendMail({
      from:    `"Pôle Jeunesse Nogent" <${process.env.SMTP_USER}>`,
      to:      data.email,
      subject: data.subject || 'Vos identifiants Pôle Jeunesse',
      text:    buildText(data.prenom, data.username, data.password, data.introText),
      html:    buildHtml(data.prenom, data.username, data.password, data.introText),
    });
    console.log('[EMAIL] Identifiants envoyés');
    return { success: true };
  } catch (err: any) {
    console.error('[EMAIL] Erreur envoi identifiants:', err);
    return { success: false, error: err?.message ?? 'Erreur inconnue' };
  }
}

// ─── Email : réinitialisation mot de passe ────────────────────────────────────

export async function envoyerReinitialisationMdp(data: {
  prenom: string; nom: string; email: string;
  username: string; password: string;
}): Promise<{ success: boolean; error?: string }> {
  try {
    const transporter = createTransporter();
    await transporter.sendMail({
      from:    `"Pôle Jeunesse Nogent" <${process.env.SMTP_USER}>`,
      to:      data.email,
      subject: 'Vos identifiants Pôle Jeunesse',
      text:    buildText(data.prenom, data.username, data.password),
      html:    buildHtml(data.prenom, data.username, data.password),
    });
    console.log('[EMAIL] Réinitialisation MDP envoyée');
    return { success: true };
  } catch (err: any) {
    console.error('[EMAIL] Erreur réinitialisation:', err);
    return { success: false, error: err?.message ?? 'Erreur inconnue' };
  }
}

// ─── Email : lien de réinitialisation (jeton à usage unique) ──────────────────

/**
 * Les valeurs interpolées ici viennent de la fiche animateur (saisie libre) :
 * on les échappe pour qu'un prénom contenant du HTML ne puisse pas réécrire le
 * courriel (faux lien de connexion, par exemple).
 */
function echapperHtml(valeur: string): string {
  return valeur
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function buildResetLinkHtml(prenom: string, username: string, lien: string, expireMinutes: number): string {
  const p = echapperHtml(prenom);
  const u = echapperHtml(username);
  const l = echapperHtml(lien);
  return `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Réinitialisation de votre mot de passe</title>
</head>
<body style="margin:0;padding:0;background:#f0edf5;font-family:Arial,Helvetica,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#f0edf5;padding:40px 16px;">
    <tr><td align="center">
      <table width="540" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:18px;overflow:hidden;box-shadow:0 6px 32px rgba(107,26,110,0.13);">
        <tr>
          <td style="background:#6B1A6E;padding:24px 36px;text-align:center;">
            <img src="${LOGO_B64}" alt="Pôle Jeunesse" width="180" style="display:block;margin:0 auto;max-width:180px;height:auto;" />
          </td>
        </tr>
        <tr>
          <td style="padding:36px 36px 28px;">
            <p style="margin:0 0 6px;font-size:20px;font-weight:700;color:#1a1a2e;">Bonjour ${p},</p>
            <p style="margin:0 0 20px;font-size:14px;color:#555;line-height:1.7;">
              Une réinitialisation du mot de passe a été demandée pour le compte
              <strong style="font-family:'Courier New',monospace;">${u}</strong>.<br/>
              Clique sur le bouton ci-dessous pour choisir un nouveau mot de passe.
            </p>
            <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:20px;">
              <tr>
                <td align="center">
                  <a href="${l}" style="display:inline-block;background:#1B3870;color:#ffffff;font-weight:700;font-size:14px;padding:13px 36px;border-radius:10px;text-decoration:none;">
                    Choisir un nouveau mot de passe
                  </a>
                </td>
              </tr>
            </table>
            <p style="margin:0 0 10px;font-size:12px;color:#888;line-height:1.7;">
              Ce lien est valable <strong>${expireMinutes} minutes</strong> et ne peut servir qu'une seule fois.
              Ton mot de passe actuel reste inchangé tant que tu n'as pas utilisé ce lien.
            </p>
            <p style="margin:0;font-size:12px;color:#888;line-height:1.7;">
              Si tu n'es pas à l'origine de cette demande, ignore ce message : rien ne sera modifié.
            </p>
          </td>
        </tr>
        <tr>
          <td style="padding:14px 36px 18px;background:#f0edf5;">
            <p style="margin:0;font-size:11px;color:#bbb;text-align:center;line-height:1.6;">
              Ce message est généré automatiquement — Ne pas répondre directement à cet email.
            </p>
          </td>
        </tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`;
}

function buildResetLinkText(prenom: string, username: string, lien: string, expireMinutes: number): string {
  return `Bonjour ${prenom},

Une réinitialisation du mot de passe a été demandée pour le compte ${username}.

Pour choisir un nouveau mot de passe, ouvre ce lien :
${lien}

Ce lien est valable ${expireMinutes} minutes et ne peut servir qu'une seule fois.
Ton mot de passe actuel reste inchangé tant que tu n'as pas utilisé ce lien.

Si tu n'es pas à l'origine de cette demande, ignore ce message : rien ne sera modifié.

Pôle Jeunesse`;
}

/**
 * Envoie le lien de réinitialisation. Contrairement aux deux envois ci-dessus,
 * ce courriel ne contient AUCUN mot de passe : le lien ne fait qu'autoriser le
 * titulaire à en choisir un.
 *
 * Le lien n'est jamais journalisé (il vaut un accès au compte tant qu'il n'a
 * pas expiré).
 */
export async function envoyerLienReinitialisation(data: {
  prenom: string; email: string; username: string;
  lien: string; expireMinutes: number;
}): Promise<{ success: boolean; error?: string }> {
  try {
    const transporter = createTransporter();
    await transporter.sendMail({
      from:    `"Pôle Jeunesse" <${process.env.SMTP_USER}>`,
      to:      data.email,
      subject: 'Réinitialisation de votre mot de passe — Pôle Jeunesse',
      text:    buildResetLinkText(data.prenom, data.username, data.lien, data.expireMinutes),
      html:    buildResetLinkHtml(data.prenom, data.username, data.lien, data.expireMinutes),
    });
    console.log('[EMAIL] Lien de réinitialisation envoyé');
    return { success: true };
  } catch (err: unknown) {
    console.error('[EMAIL] Erreur envoi lien de réinitialisation:', err instanceof Error ? err.message : err);
    return { success: false, error: err instanceof Error ? err.message : 'Erreur inconnue' };
  }
}

// ─── Email : alerte de monitoring ─────────────────────────────────────────────

function echapper(texte: string): string {
  return texte.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/**
 * Alerte envoyée à MAIL_ADMIN quand un événement de monitoring survient (au
 * plus une fois par type toutes les 30 minutes — voir lib/monitoring.ts).
 * Le courriel ne contient que le type, le message et le chemin : jamais la
 * pile d'appels ni le détail, consultables sur la page Monitoring.
 * Sans SMTP ou sans MAIL_ADMIN configuré, rien n'est envoyé (ce n'est pas une
 * erreur : l'événement reste dans le journal).
 */
export async function envoyerAlerteMonitoring(evenement: {
  type: string; message: string; path?: string | null; at: string;
}): Promise<{ success: boolean; error?: string }> {
  const destinataire = process.env.MAIL_ADMIN?.trim();
  if (!destinataire || !process.env.SMTP_HOST?.trim()) return { success: false, error: 'Alerte non configurée' };
  try {
    const transporter = createTransporter();
    const quand = new Date(evenement.at).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'medium', timeStyle: 'short' });
    await transporter.sendMail({
      from:    `"Pôle Jeunesse — Monitoring" <${process.env.SMTP_USER}>`,
      to:      destinataire,
      subject: `🐛 ${evenement.type}`,
      text:    `${evenement.type}\n${evenement.message}\n${evenement.path ?? ''}\n${quand}\n\nDétail : page Monitoring de l'administration.`,
      html:    `<div style="font-family:sans-serif;font-size:14px;color:#1e1b4b">
        <p style="margin:0 0 8px"><strong>${echapper(evenement.type)}</strong></p>
        <p style="margin:0 0 8px">${echapper(evenement.message)}</p>
        ${evenement.path ? `<p style="margin:0 0 8px;color:#64748b">${echapper(evenement.path)}</p>` : ''}
        <p style="margin:0;color:#64748b;font-size:12px">${echapper(quand)} — détail sur la page Monitoring de l'administration.</p>
      </div>`,
    });
    return { success: true };
  } catch (err: unknown) {
    return { success: false, error: err instanceof Error ? err.message : 'Erreur inconnue' };
  }
}
